js "(() => {
  const r = window.__qa.results().filter((x) => x.game === 'arm');
  const card = (() => {
  const r = window.__qa.results().filter((x) => x.game === 'arm');
  const bad = r.filter((x) => !(x.card && x.card.shown && x.card.heldOn && x.card.frozen));
  return bad.length === 0 || 'card not shown or not holding the game in match(es) ' + bad.map((x) => x.match).join(', ');
})();
  if (card !== true) return card;
  const stolen = r.every((x) => x.tellsTaken === x.tells);
  const won = r.filter((x) => x.verdict === 'win').length;
  if (r.length < 6) return 'only ' + r.length + ' of 6 matches finished';
  if (!stolen) return 'a flash answered at 0.3 s did not become a steal: ' + JSON.stringify(r.map((x) => [x.tellsTaken, x.tells]));
  return won >= 1 || 'no win in 6 matches: ' + JSON.stringify(r.map((x) => x.verdict));
})()"

