js "(() => {
  const r = window.__qa.results().filter((x) => x.game === 'claw');
  const card = (() => {
  const r = window.__qa.results().filter((x) => x.game === 'claw');
  const bad = r.filter((x) => !(x.card && x.card.shown && x.card.heldOn && x.card.frozen));
  return bad.length === 0 || 'card not shown or not holding the game in match(es) ' + bad.map((x) => x.match).join(', ');
})();
  if (card !== true) return card;
  if (r.length < 4) return 'only ' + r.length + ' of 4 matches finished';
  if (!r.every((x) => x.tellsTaken >= 1)) return 'a match took no glint: ' + JSON.stringify(r.map((x) => [x.tellsTaken, x.tells]));
  return r.some((x) => x.verdict === 'win') || 'no win in 4 matches: ' + JSON.stringify(r.map((x) => x.verdict));
})()"

